package com.ferreteriahuaman.service;
import com.ferreteriahuaman.dto.PurchaseModels.*;
import com.ferreteriahuaman.dto.CatalogModels.*;
import com.ferreteriahuaman.repository.*;
import com.ferreteriahuaman.repository.PurchaseRepository.Kind;
import com.ferreteriahuaman.security.AuthFailure;
import com.ferreteriahuaman.security.AuthModels.Identity;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.math.*;import java.time.*;import java.util.*;
import org.springframework.context.annotation.Profile;
import org.springframework.stereotype.Service;
@Service @Profile("db")
public class PurchaseService {
 private final PurchaseRepository repo;private final ProductRepository products;private final BusinessTransactions tx;private final ObjectMapper mapper;
 public PurchaseService(PurchaseRepository repo,ProductRepository products,BusinessTransactions tx,ObjectMapper mapper){this.repo=repo;this.products=products;this.tx=tx;this.mapper=mapper;}
 private AuthFailure bad(String text){return new AuthFailure(400,text);}
 private String json(Object value){if(value==null)return null;try{return mapper.writeValueAsString(value);}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new IllegalStateException("No se pudo registrar la auditoría");}}
 private void audit(Identity a,String action,String table,long id,Object before,Object after){repo.event(a.id(),action,table,id,json(before),json(after),null);}
 private void version(LocalDateTime expected,LocalDateTime actual){if(expected==null)throw bad("Falta la versión del registro");if(!expected.equals(actual))throw new AuthFailure(409,"El registro cambió. Vuelve a cargarlo antes de guardar");}
 public void paging(String q,int page,int size){if(q.length()>100||page<0||page>1000000||size<1||size>100)throw bad("Revisa los filtros y la paginación");}
 public Page<Supplier> suppliers(String q,String state,int page,int size){paging(q,page,size);if(!state.matches("A|I|^$"))throw bad("Estado de proveedor no válido");return repo.suppliers(q.strip(),state,page,size);}
 public Supplier supplier(long id){return repo.supplier(id,false).orElseThrow(()->new AuthFailure(404,"Proveedor no encontrado"));}
 public Supplier saveSupplier(Identity a,String equipo,Long id,SupplierInput i){return tx.write(a,equipo,"PRV.GESTIONAR",()->{if(i.ruc().equals("00000000000"))throw bad("Escribe un RUC válido de once dígitos");Supplier before=id==null?null:repo.supplier(id,true).orElseThrow(()->new AuthFailure(404,"Proveedor no encontrado"));if(before!=null){version(i.version(),before.version());if(!before.ruc().equals(i.ruc())&&repo.supplierHistory(id))throw new AuthFailure(409,"El proveedor tiene documentos. No se puede cambiar su RUC histórico");}long saved;if(id==null)saved=repo.createSupplier(i);else{repo.updateSupplier(id,i);saved=id;}var result=supplier(saved);audit(a,"PRV.GUARDAR","proveedor",saved,before,result);return result;});}
 public Supplier supplierState(Identity a,String equipo,long id,StateInput i){return tx.write(a,equipo,"PRV.GESTIONAR",()->{var before=repo.supplier(id,true).orElseThrow(()->new AuthFailure(404,"Proveedor no encontrado"));version(i.version(),before.version());if(before.estado().equals(i.estado()))return before;if(i.estado().equals("I")&&repo.pendingSupplier(id))throw new AuthFailure(409,"El proveedor tiene órdenes o ingresos pendientes");repo.supplierState(id,i.estado());var result=supplier(id);audit(a,"PRV.ESTADO","proveedor",id,before,result);return result;});}
 public Page<Document> list(Kind k,String q,String state,Long supplier,int page,int size){paging(q,page,size);Set<String> states=k==Kind.ORDER?Set.of("","BORRADOR","EMITIDA","PARCIAL","COMPLETA","ANULADA"):Set.of("","BORRADOR","CONFIRMADO","ANULADO");if(!states.contains(state)||supplier!=null&&supplier<1)throw bad("Revisa el estado y proveedor seleccionados");return repo.list(k,q.strip(),state,supplier,page,size);}
 private Document document(Kind k,long id,boolean lock){return repo.get(k,id,lock).orElseThrow(()->new AuthFailure(404,"Documento no encontrado"));}
 public Details details(Kind k,long id){return new Details(document(k,id,false),repo.lines(k,id));}
 private void draft(Document d){if(!d.estado().equals("BORRADOR"))throw new AuthFailure(409,"Solo se pueden editar documentos en borrador");}
 private void validateDocument(Kind k,DocumentInput i){if(k==Kind.ORDER){if(i.guia()!=null&&!i.guia().isBlank()||i.ordenId()!=null)throw bad("Una orden no lleva guía ni orden de origen");if(i.entregaEstimada()!=null&&i.entregaEstimada().isBefore(i.fecha()))throw bad("La entrega estimada no puede ser anterior a la fecha de la orden");}else{if(i.guia()==null||i.guia().isBlank()||!i.guia().equals(i.guia().strip()))throw bad("Indica el número de guía sin espacios exteriores");if(i.entregaEstimada()!=null)throw bad("Un ingreso no lleva fecha de entrega estimada");}
  var supplier=repo.supplier(i.proveedorId(),true).orElseThrow(()->bad("Proveedor no encontrado"));if(!supplier.estado().equals("A"))throw bad("Selecciona un proveedor activo");
  if(k==Kind.RECEIPT&&i.ordenId()!=null){var order=document(Kind.ORDER,i.ordenId(),true);if(order.proveedorId()!=i.proveedorId()||!Set.of("EMITIDA","PARCIAL").contains(order.estado()))throw bad("Selecciona una orden emitida o parcial del mismo proveedor");}
 }
 public Details save(Identity a,String equipo,Kind k,Long id,DocumentInput i){return tx.write(a,equipo,k.permission,()->{
  if(id==null){if(i.clave()==null)throw bad("Falta la clave de la solicitud");var previous=repo.creationRetry(a.id(),k.permission+"_CREAR",i.clave(),json(i));if(previous.isPresent())return details(k,previous.get());validateDocument(k,i);long saved=repo.create(k,i);var result=details(k,saved);repo.event(a.id(),k.permission+"_CREAR",k.table,saved,null,json(Map.of("solicitud",i,"documento",result)),i.clave());return result;}
  var before=document(k,id,true);version(i.version(),before.version());draft(before);if(before.proveedorId()!=i.proveedorId()||!Objects.equals(before.ordenId(),i.ordenId()))throw bad("El proveedor y la orden de origen se conservan en este documento");validateDocument(k,i);repo.update(k,id,i);var result=details(k,id);audit(a,k.permission+"_EDITAR",k.table,id,before,result);return result;
 });}
 private Line line(Kind k,long doc,long id){return repo.lines(k,doc).stream().filter(l->l.id()==id).findFirst().orElseThrow(()->new AuthFailure(404,"Línea no encontrada en este documento"));}
 private void validateLine(Kind k,Document d,LineInput i,Long edited){
  var product=products.get(i.productoId(),true,false).orElseThrow(()->bad("Producto no encontrado"));var p=products.presentation(i.presentacionId(),true).orElseThrow(()->bad("Presentación no encontrada"));if(!product.estado().equals("A")||!p.estado().equals("A")||p.productoId()!=product.id())throw bad("Selecciona un producto y una presentación activos compatibles");
  if(!p.admiteFracciones()&&i.cantidad().stripTrailingZeros().scale()>0)throw bad("La presentación de compra no admite fracciones");BigDecimal base=i.cantidad().multiply(new BigDecimal(p.factorBase()));if(base.remainder(new BigDecimal(product.incrementoBase())).signum()!=0)throw bad("La cantidad no respeta el incremento base del producto");if(base.compareTo(new BigDecimal("999999999999.999999"))>0||i.cantidad().multiply(i.costoUnitario()).setScale(2,RoundingMode.HALF_UP).signum()<=0)throw bad("Revisa la cantidad y el importe de la línea");
  if(k==Kind.ORDER){if(i.detalleOrdenId()!=null||i.condicion()!=null||i.piezas()!=null)throw bad("La condición física se registra al recibir mercadería");return;}
  if(i.condicion()==null)throw bad("Selecciona la condición física de la recepción");
  if(product.modoControl().equals("GRANEL")&&!i.condicion().equals("GRANEL")||product.modoControl().equals("ENVASES")&&!Set.of("ENVASE","GRANEL").contains(i.condicion())||product.modoControl().equals("TRAMOS")&&!i.condicion().equals("TRAMO"))throw bad("La condición física no corresponde al control del producto");
  if(i.condicion().equals("GRANEL")&&i.piezas()!=null||!i.condicion().equals("GRANEL")&&i.piezas()==null)throw bad("Indica piezas solo para envases o tramos");
  if(i.condicion().equals("ENVASE")&&(p.unidadVentaId()!=null||i.cantidad().compareTo(BigDecimal.valueOf(i.piezas()))!=0))throw bad("Cada envase requiere una presentación comercial completa y una pieza");
  if(i.condicion().equals("TRAMO")&&base.remainder(new BigDecimal(product.incrementoBase()).multiply(BigDecimal.valueOf(i.piezas()))).signum()!=0)throw bad("La longitud por pieza no respeta el incremento del producto");
  if(d.ordenId()==null){if(i.detalleOrdenId()!=null)throw bad("La recepción sin orden no puede vincular una línea de orden");}
  else{var source=line(Kind.ORDER,d.ordenId(),Objects.requireNonNullElse(i.detalleOrdenId(),0L));if(!source.estado().equals("A")||source.productoId()!=i.productoId()||source.presentacionId()!=i.presentacionId())throw bad("La línea no corresponde a la orden de origen");BigDecimal reserved=repo.lines(k,d.id()).stream().filter(l->l.estado().equals("A")&&Objects.equals(l.detalleOrdenId(),i.detalleOrdenId())&&(edited==null||l.id()!=edited)).map(l->new BigDecimal(l.cantidadBase())).reduce(BigDecimal.ZERO,BigDecimal::add);if(base.add(reserved).compareTo(new BigDecimal(source.cantidadBase()).subtract(new BigDecimal(source.recibidoBase())))>0)throw bad("La recepción supera la cantidad pendiente de la orden");}
 }
 public Details saveLine(Identity a,String equipo,Kind k,long doc,Long id,LineInput i){return tx.write(a,equipo,k.permission,()->{var d=document(k,doc,true);version(i.version(),d.version());draft(d);Line before=id==null?null:line(k,doc,id);if(before!=null&&(before.productoId()!=i.productoId()||before.presentacionId()!=i.presentacionId()||!Objects.equals(before.detalleOrdenId(),i.detalleOrdenId())))throw bad("La identidad de una línea no se reasigna. Desactívala y añade otra");validateLine(k,d,i,id);long saved;if(id==null)saved=repo.addLine(k,doc,i);else{repo.updateLine(k,id,i);saved=id;}audit(a,k.permission+"_LINEA",k.lines,saved,before,line(k,doc,saved));return details(k,doc);});}
 public Details lineState(Identity a,String equipo,Kind k,long doc,long id,StateInput i){return tx.write(a,equipo,k.permission,()->{var d=document(k,doc,true);version(i.version(),d.version());draft(d);var before=line(k,doc,id);if(before.estado().equals(i.estado()))return details(k,doc);if(i.estado().equals("A"))validateLine(k,d,new LineInput(before.productoId(),before.presentacionId(),new BigDecimal(before.cantidad()),new BigDecimal(before.costoUnitario()),before.detalleOrdenId(),before.condicion(),before.piezas(),d.version()),id);repo.lineState(k,id,i.estado());audit(a,k.permission+"_LINEA_ESTADO",k.lines,id,before,line(k,doc,id));return details(k,doc);});}
 public Details process(Identity a,String equipo,Kind k,long id,Action i,boolean cancel){String permission=cancel&&k==Kind.ORDER?"COM.OC_ANULAR":k.permission;return tx.write(a,equipo,permission,()->{var before=document(k,id,true);boolean retry=cancel?repo.cancelRetry(k,id,i.clave()):repo.retry(k,id,i.clave());if(!retry)version(i.version(),before.version());if(cancel&&(i.motivo()==null||i.motivo().strip().length()<10))throw bad("Indica un motivo de anulación de al menos 10 caracteres");repo.process(k,id,i.clave(),cancel,i.motivo());return details(k,id);});}
 public OpeningResult opening(Identity a,String equipo,Opening i){return tx.write(a,equipo,"INV.APERTURA",()->{var list=new ArrayList<Map<String,Object>>();for(var u:i.unidades()){var value=new LinkedHashMap<String,Object>();value.put("identificador",u.identificador());value.put("condicion",u.condicion());value.put("cantidad",u.cantidad());value.put("id_presentacion",u.presentacionId());list.add(value);}return new OpeningResult(repo.opening(i,json(list)));});}
 public Page<Movement> movements(Identity a,long product,int page,int size){paging("",page,size);products.get(product,false,false).orElseThrow(()->new AuthFailure(404,"Producto no encontrado"));return repo.movements(product,page,size,a.permisos().contains("PRO.COSTOS"));}
 public Page<Existence> existences(long product,int page,int size){paging("",page,size);products.get(product,false,false).orElseThrow(()->new AuthFailure(404,"Producto no encontrado"));return repo.existences(product,page,size);}
}
